/* From Uiverse.io by joe-watson-sbf - Tags: card, hover */
.__UIV_SCOPE__ .card {
  width: 210px;
  height: 254px;
  border-radius: 4px;
  background: #212121;
  display: flex;
  gap: 5px;
  padding: .4em;
}

.__UIV_SCOPE__ .card p {
  height: 100%;
  flex: 1;
  overflow: hidden;
  cursor: pointer;
  border-radius: 2px;
  transition: all .5s;
  background: #212121;
  border: 1px solid #ff5a91;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .card p:hover {
  flex: 4;
}

.__UIV_SCOPE__ .card p span {
  min-width: 14em;
  padding: .5em;
  text-align: center;
  transform: rotate(-90deg);
  transition: all .5s;
  text-transform: uppercase;
  color: #ff568e;
  letter-spacing: .1em;
}

.__UIV_SCOPE__ .card p:hover span {
  transform: rotate(0);
}
